{
  "technical_and_design_decisions": [
    "Extend the existing Go-based fabric-config package with new methods following established patterns for config group modification.",
    "Maintain backward compatibility: keep existing Get/SetConfiguration and Get/SetMSP methods while adding new granular setters.",
    "Implement a shared internal helper for MSP org groups to avoid duplicating individual setter logic across OrdererOrgGroup, ApplicationOrgGroup, and ConsortiumOrgGroup.",
    "For OrdererGroup setters, read current configuration via existing getters and persist unrelated fields when applying partial updates.",
    "Refactor config update signing so that building a ConfigUpdateEnvelope is separated from signing, exposing an unsigned builder (U2).",
    "Implement removal functions for legacy top-level OrdererAddresses and KafkaBrokers that delete the corresponding config keys; genesis creation logic will omit these keys and rely on org-level endpoints.",
    "For the CLI tool (U6), create a new Go command-line binary using standard flags (or Cobra) that parses JSON operation specs, uses a Fabric connection profile to instantiate a discovery client, applies updates via the fabric-config API, and supports dry-run output as well as signed submission.",
    "Consenter removal matches all four identifying fields (host, port, client TLS cert, server TLS cert) to ensure safety.",
    "Operation stacking in the CLI is performed by processing the operations array sequentially per channel."
  ],
  "assumptions": [
    "The developer is experienced with Go and the Hyperledger Fabric codebase, requiring no learning time.",
    "The fabric-config library already provides low-level config group primitives; the work only adds higher-level API functions and a CLI.",
    "The CLI tool is delivered as a new binary inside the fabric-config repository.",
    "Connection profile and signing identity JSON formats follow the Fabric 2.0 specification exactly as described in the user story.",
    "A local or containerized Fabric test network is available for integration testing of the CLI and config updates.",
    "Effort estimates include writing unit tests and updating code examples, but exclude CI pipeline configuration and release management.",
    "Estimates are for a single developer's work-hours, not calendar elapsed time."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Add consortium to consortiums group (U1)",
      "activity_description": "Implement AddConsortium function on the consortiums group, handle case with no orgs, and update examples to demonstrate adding a consortium plus orgs. Includes unit tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "Unsigned config update envelope (U2)",
      "activity_description": "Refactor config update generation to expose a function that returns a cb.ConfigUpdateEnvelope without requiring signing identities at generation time. Includes unit tests.",
      "most_likely_effort": 7
    },
    {
      "activity_id": "A3",
      "activity_name": "Remove legacy orderer addresses (U3)",
      "activity_description": "Implement RemoveLegacyOrdererAddresses on the channel group and modify new channel/genesis config creation to omit top-level OrdererAddresses, requiring org-level endpoints at creation. Includes unit tests.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A4",
      "activity_name": "Remove KafkaBrokers section (U4)",
      "activity_description": "Implement function to entirely remove KafkaBrokers from config and add/improve example showing Kafka to EtcdRaft migration. Includes unit tests.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A5",
      "activity_name": "Add/remove consenters for EtcdRaft (U5)",
      "activity_description": "Implement AddConsenter and RemoveConsenter functions for etcdraft orderer configuration; removal matches all four fields (host, port, client cert, server cert). Includes unit tests.",
      "most_likely_effort": 11
    },
    {
      "activity_id": "A6",
      "activity_name": "OrdererGroup individual setters (U7)",
      "activity_description": "Implement SetMaxMessageCount, SetAbsoluteMaxBytes, SetPreferredMaxBytes, SetBatchTimeout, SetMaxChannels, SetConsensusType, SetConsensusState, and individual EtcdRaftMetadata modifiers on OrdererGroup; keep existing Get/SetConfiguration. Update examples. Includes unit tests.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A7",
      "activity_name": "Org MSP individual setters (U8)",
      "activity_description": "Implement Add/Remove functions for RootCert, IntermediateCert, AdminCert, CRL, OUIdentifier, TLS certs, CryptoConfig, OU identifiers, and Enable/DisableNodeOUs for OrdererOrgGroup, ApplicationOrgGroup, and ConsortiumOrgGroup using shared helpers. Update examples. Includes unit tests.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "A8",
      "activity_name": "Bulk channel CLI tool (U6)",
      "activity_description": "Develop CLI tool consuming fabric-config library: parse batchUpdate.json, connection profile, and signing identities; support consenter, MSP, and anchor peer operations; multi-channel loop; dry-run flag; service discovery for config fetch; sign and submit. Include examples and tests.",
      "most_likely_effort": 50
    },
    {
      "activity_id": "A9",
      "activity_name": "Integration testing and documentation finalization",
      "activity_description": "Perform cross-feature integration tests, verify CLI end-to-end against a test network, and finalize documentation and example consistency.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 162
  }
}

